const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
      [[[68.0, 23.8],
        [68.0, 28.7],
        [70.5, 28.7],
        [70.5, 23.8]]], null, false); // A significant portion of the Indus River floodplain in Sindh province, Pakistan

  const date1_start = '2022-07-01';
  const date1_end = '2022-07-31';
  const date2_start = '2022-08-01';
  const date2_end = '2022-08-28';

  const s1_collection = ee.ImageCollection('COPERNICUS/S1_GRD_FLOAT')
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING'))
      .filterBounds(geometry)
      .select('VV');

  // Function to apply speckle filter
  function applySpeckleFilter(image) {
    return image.focal_median(3, 'square', 'pixels');
  }

  // Function to process Sentinel-1 and get water mask
  function getWaterMask(imageCollection, geom) {
    const count = imageCollection.size().getInfo();
    if (count === 0) {
      return null; // Indicates an empty collection
    }

    let composite = imageCollection.median();
    composite = applySpeckleFilter(composite);

    // Apply a threshold to detect water. Water generally has very low backscatter.
    // A common threshold for VV is around -18 to -15 dB. Let's use -18 dB,
    // which is approximately 0.0158 in linear scale.
    // Convert to linear first if it's not already, and then apply threshold.
    // The collection is already FLOAT, so it's linear.
    const water = composite.lt(0.0158); // Threshold for water detection (linear scale)

    // Mask non-water areas
    const waterMasked = water.updateMask(water);
    return waterMasked.clip(geom);
  }

  // Calculate water area for Period 1
  const s1_col1 = s1_collection.filterDate(date1_start, date1_end);
  const waterMask1 = getWaterMask(s1_col1, geometry);

  if (waterMask1 === null) {
    console.log("Period 1 Images: 0");
    console.log("C1");
    return;
  }

  // Calculate pixel count for Period 1
  const pixelCount1 = waterMask1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30, // Sentinel-1 resolution
    maxPixels: 1e9
  }).get('VV').getInfo();

  if (pixelCount1 === 0) {
    console.log(`Period 1 Images: ${s1_col1.size().getInfo()}`);
    console.log("Period 1 Water Pixels: 0");
    console.log("C2");
    return;
  }

  const waterArea1 = waterMask1.multiply(ee.Image.pixelArea()).divide(1e6) // convert to square kilometers
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 30,
        maxPixels: 1e9
      }).get('VV').getInfo();

  // Validate waterArea1
  if (waterArea1 === null || isNaN(waterArea1)) {
    console.log(`Period 1 Images: ${s1_col1.size().getInfo()}`);
    console.log(`Period 1 Water Pixels: ${pixelCount1}`);
    console.log("C3");
    return;
  }

  // Calculate water area for Period 2
  const s1_col2 = s1_collection.filterDate(date2_start, date2_end);
  const waterMask2 = getWaterMask(s1_col2, geometry);

  if (waterMask2 === null) {
    console.log("Period 2 Images: 0");
    console.log("C1");
    return;
  }

  // Calculate pixel count for Period 2
  const pixelCount2 = waterMask2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('VV').getInfo();

  if (pixelCount2 === 0) {
    console.log(`Period 2 Images: ${s1_col2.size().getInfo()}`);
    console.log("Period 2 Water Pixels: 0");
    console.log("C2");
    return;
  }

  const waterArea2 = waterMask2.multiply(ee.Image.pixelArea()).divide(1e6) // convert to square kilometers
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 30,
        maxPixels: 1e9
      }).get('VV').getInfo();

  // Validate waterArea2
  if (waterArea2 === null || isNaN(waterArea2)) {
    console.log(`Period 2 Images: ${s1_col2.size().getInfo()}`);
    console.log(`Period 2 Water Pixels: ${pixelCount2}`);
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Period 1 (Jul 2022) Images: ${s1_col1.size().getInfo()} (Water Pixels: ${pixelCount1})`);
  console.log(`Period 1 Water Area: ${waterArea1.toFixed(2)} km^2`);
  console.log(`Period 2 (Aug 2022) Images: ${s1_col2.size().getInfo()} (Water Pixels: ${pixelCount2})`);
  console.log(`Period 2 Water Area: ${waterArea2.toFixed(2)} km^2`);

  // Define a threshold for "increase". Given the flood context, any significant increase is relevant.
  // Let's consider a 10% increase as significant or an absolute increase of at least 100 km^2.
  const increasePercentage = ((waterArea2 - waterArea1) / waterArea1) * 100;
  const absoluteIncrease = waterArea2 - waterArea1;

  if (absoluteIncrease > 0 && increasePercentage > 10) { // Check for increase AND significant percentage
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
